$nu = @{}; foreach ($f in $lage['1.0.21'].Keys) { $nu[$f] = Las $f }
$h = @{}; foreach ($f in $nu.Keys) { $h[$f] = Hash $nu[$f] }
$start = $null
for ($k = $utgavor.Count - 1; $k -ge 0; $k--) {
    $v = $utgavor[$k]; $ok = $true
    foreach ($f in $lage[$v].Keys) { if ($h[$f] -ne $lage[$v][$f]) { $ok = $false; break } }
    if ($ok) { $start = $k; break }
}
$olika = @($lage['1.0.21'].Keys | Sort-Object | Where-Object { $h[$_] -ne $lage['1.0.21'][$_] })
if ($Visa) {
    foreach ($f in $olika) {
        $din = @(if ($nu[$f] -ne $null) { $nu[$f] -split "`n" | ForEach-Object { $_.TrimEnd() } })
        $sid = @(if ($sida14[$f]) { (Txt $sida14[$f]) -split "`n" | ForEach-Object { $_.TrimEnd() } })
        $d = @(Compare-Object $din $sid)
        Write-Host "== $f  (bara hos dig: $(@($d | Where-Object SideIndicator -eq '<=').Count) rader, bara pa sidan: $(@($d | Where-Object SideIndicator -eq '=>').Count) rader)"
        $d | Select-Object -First 12 | ForEach-Object { if ($_.SideIndicator -eq '<=') { "  din:   $($_.InputObject)" } else { "  sidan: $($_.InputObject)" } }
    }
    exit 0
}
if ($start -eq $null -and $SidanFore) {
    $kopia14 = Join-Path $env:TEMP ('spektro-fore-sidan14-' + (Get-Date -Format 'yyyyMMdd-HHmmss'))
    foreach ($f in $olika) {
        $p = Join-Path $Rot $f
        if (Test-Path -LiteralPath $p) { $b = Join-Path $kopia14 $f; New-Item -ItemType Directory -Force (Split-Path $b) | Out-Null; Copy-Item -LiteralPath $p $b }
        $nu[$f] = if ($sida14[$f]) { Txt $sida14[$f] } else { $null }
        Write-Host "  sidans version efter 1.0.21: $f"
    }
    Write-Host "Dina versioner av dem: $kopia14"
    $start = 0
}
if ($start -eq $null) {
    Write-Host 'Filerna stammer inte exakt med sidan efter nagon utgava 1.0.21-1.0.46. De som skiljer fran laget efter 1.0.21:'
    $olika | ForEach-Object { Write-Host "  $_" }
    Write-Host 'Se skillnaderna:              powershell -ExecutionPolicy Bypass -File .\spektro-1.0.22-1.0.46.ps1 -Visa'
    Write-Host 'Ta sidans version och fortsatt: powershell -ExecutionPolicy Bypass -File .\spektro-1.0.22-1.0.46.ps1 -SidanFore'
    Write-Host 'Forsoker anda fran 1.0.22 (inget skrivs om ett steg inte gar igenom).'
    $start = 0
} else { Write-Host "Projektet ar som sidan efter $($utgavor[$start])." }
$fore = $utgavor[$start]; $gjorda = 0
foreach ($r in $steg) {
    $v, $n, $fil, $typ, $g64, $n64 = $r
    if ([version]$v -le [version]$fore) { continue }
    $ny = Txt $n64; $t = $nu[$fil]; $namn = "$v steg $n ($typ $fil)"
    if ($typ -eq 'byt') {
        $gammal = Txt $g64
        if ($t -eq $null) { Write-Host "STOPP $namn`n  filen finns inte. Inget har skrivits."; exit 1 }
        $c = Antal $t $gammal
        if ($c -ne 1) { Write-Host "STOPP $namn`n  den roda texten finns $c ganger (ska vara 1). Inget har skrivits."; exit 1 }
        $i = $t.IndexOf($gammal, [StringComparison]::Ordinal); $t = $t.Substring(0, $i) + $ny + $t.Substring($i + $gammal.Length)
    } elseif ($typ -eq 'lagg_till') {
        if ($t -eq $null) { $t = '' }
        if ($t -ne '' -and -not $t.EndsWith("`n")) { $t += "`n" }
        $t += $ny
    } else { $t = $ny }
    $nu[$fil] = $t; $gjorda++
}
if ($gjorda -eq 0) { Write-Host 'Inget att gora: allt till och med 1.0.46 finns redan.' } else {
    $kopia = Join-Path $env:TEMP ('spektro-fore-1.0.22-' + (Get-Date -Format 'yyyyMMdd-HHmmss'))
    $skrivna = 0
    foreach ($f in $nu.Keys) {
        if ($nu[$f] -eq $null -or (Las $f) -ceq $nu[$f]) { continue }
        $p = Join-Path $Rot $f
        if (Test-Path -LiteralPath $p) { $b = Join-Path $kopia $f; New-Item -ItemType Directory -Force (Split-Path $b) | Out-Null; Copy-Item -LiteralPath $p $b }
        New-Item -ItemType Directory -Force (Split-Path $p) | Out-Null
        [IO.File]::WriteAllText($p, $nu[$f], $utf8); $skrivna++
    }
    Write-Host "Steg gjorda: $gjorda (fran $fore till 1.0.46), filer skrivna: $skrivna"
    if (Test-Path $kopia) { Write-Host "Dina tidigare versioner: $kopia" }
}
Set-Location $Rot
$OutputEncoding = $utf8; [Console]::OutputEncoding = $utf8; $env:PYTHONUTF8 = '1'; $env:MPLBACKEND = 'Agg'
$ErrorActionPreference = 'Continue'
$py = Join-Path $Rot '.venv\Scripts\python.exe'
if (-not (Test-Path $py)) { $py = Join-Path $Rot '.venv/bin/python' }
if (-not (Test-Path $py)) { $py = 'python' }
Write-Host "Python: $py"
& $py -m ruff check .
& $py -m pytest -q | Select-Object -Last 3
$norm = { param($x) ($x -replace 'data/(\d{8}|\S{8})-(\d{6}|HHMMSS)(-\d+)?', 'data/MAPP' -replace 'residual: -?[0-9.]+e-1\d', 'residual: 0').TrimEnd() }
foreach ($f in Get-ChildItem tests/kommandon -Filter 'testa_*.txt' | Sort-Object Name) {
    $facit = Join-Path $f.DirectoryName ($f.Name -replace '^testa_', 'facit_')
    if (-not (Test-Path $facit)) { continue }
    $a = @(Get-Content $f.FullName -Encoding UTF8 | & $py -W error -m spectrometer.main 2>&1 | ForEach-Object { & $norm "$_" })
    $c = @(Get-Content $facit -Encoding UTF8 | ForEach-Object { & $norm $_ })
    while ($a.Count -and $a[-1] -eq '') { $a = @($a[0..($a.Count - 2)]) }
    while ($c.Count -and $c[-1] -eq '') { $c = @($c[0..($c.Count - 2)]) }
    $lika = ($a.Count -eq $c.Count) -and (@(Compare-Object $a $c -SyncWindow 0).Count -eq 0)
    Write-Host ('{0,-14} {1}' -f $f.Name, $(if ($lika) { 'lika facit' } else { 'SKILJER fran facit' }))
}
